//github.com/we-solve/research/blob/main/problems/9b/prb_9be162952e464980899eaf1bfb69cd6d/statement.tex"}},"30007227":{"id":30007227,"problem_number":"LOCAL-30007227","legacy_ids":[],"title":"Condensation in every dilute hard-sphere ground state","collection":"ranked","rank":2771,"domain":"physics","domain_label":"Mathematical Physics","exact_target":"Are there absolute $\\epsilon _0,c_0>0$ such that for every $a,\\rho >0$ with rho $a^3<\\epsilon _0$, every thermodynamic sequence N,L$\\to$infinity with $N/L^3\\to \\rho $, and every normalized bosonic hard-sphere ground eigenvector, the limiting lower condensate fraction is at least $c_0$?","definition_tex":"\\subsection{Definitions and mathematical statement}\n\\paragraph{Statement recorded in the supplied source.}\nAre there absolute $\\epsilon _0,c_0>0$ such that for every $a,\\rho >0$ with rho $a^3<\\epsilon _0$, every thermodynamic sequence N,L$\\to$infinity with $N/L^3\\to \\rho $, and every normalized bosonic hard-sphere ground eigenvector, the limiting lower condensate fraction is at least $c_0$?\n\n\\subsection{Short English statement}\nAre there absolute $\\epsilon _0,c_0>0$ such that for every $a,\\rho >0$ with rho $a^3<\\epsilon _0$, every thermodynamic sequence N,L$\\to$infinity with $N/L^3\\to \\rho $, and every normalized bosonic hard-sphere ground eigenvector, the limiting lower condensate fraction is at least $c_0$?\n\n\\subsection{Sources}\n\\begin{itemize}\n\\item[S1] Original question source or mathematical context.\n\\url{https://github.com/openai/math/blob/adc7f1241b42e322a6451854ab7e4b4c146bf78a/preprints/Ground-state-condensation-in-the-dilute-hard-sphere-gas-September-24-2026/build/sections/introduction.tex}.\n\\item[S2] OpenAI, manuscript citation page. Source of the formulation motivating this local problem.\n\\url{https://github.com/openai/math/blob/adc7f1241b42e322a6451854ab7e4b4c146bf78a/preprints/Ground-state-condensation-in-the-dilute-hard-sphere-gas-September-24-2026/README.md}.\n\\end{itemize}","definition_file":"attacks/open_problems/top_problems/definitions/30007227.tex","link":null,"external_url":null,"sources":[{"citation":"Original question source or mathematical context.","url":"https://github.com/openai/math/blob/adc7f1241b42e322a6451854ab7e4b4c146bf78a/preprints/Ground-state-condensation-in-the-dilute-hard-sphere-gas-September-24-2026/build/sections/introduction.tex"},{"citation":"OpenAI, manuscript citation page. Source of the formulation motivating this local problem.","url":"https://github.com/openai/math/blob/adc7f1241b42e322a6451854ab7e4b4c146bf78a/preprints/Ground-state-condensation-in-the-dilute-hard-sphere-gas-September-24-2026/README.md"}],"status":"solved","status_statement":null,"status_qualification":null,"status_reviewed_at":null,"attacks":[{"model":"OpenAI","status":"solved","entry_kind":"external_claim","claimant":"OpenAI","openai":{"schema_version":1,"source_repo":"https://github.com/openai/math","source_commit":"adc7f1241b42e322a6451854ab7e4b4c146bf78a","release_date":"2026-10-06","match":"full","resolution":"proved","independently_reviewed":false,"second_pass":"agreed","families":[{"family":"267","title":"Positive-temperature Bose–Einstein condensation and exact quantum depletion","subject":"Mathematical physics","manuscripts":[{"title":"Ground-state condensation in the dilute hard-sphere gas","pdf_path":"preprints/Ground-state-condensation-in-the-dilute-hard-sphere-gas-September-24-2026/paper.pdf","readme_path":"preprints/Ground-state-condensation-in-the-dilute-hard-sphere-gas-September-24-2026/README.md","date":"2026-09-24","theorem_ref":"main:theorem (sections/introduction.tex:48)","statement_sources":[{"path":"preprints/Ground-state-condensation-in-the-dilute-hard-sphere-gas-September-24-2026/build/sections/introduction.tex","line":48,"label":"main:theorem"}]}],"lean":{"doc_path":"lean/docs/267.md","comparators":["lean/ComparatorChallenges/HardSphere.json","lean/ComparatorChallenges/HardSphere.lean"],"declarations":[],"covers_main_theorem":true},"reasoning_trace":null}]},"completion":100,"date_posted":"2026-10-06","file_path":"attacks/open_problems/top_problems/openai/30007227.tex","version":1,"we_solve":{"alias":"TOP-30007227-A1","revision":"r1","url":"https://we-solve.github.io/contributions/condensation-in-every-dilute-hard-sphere-ground-state/attempt-1/r1/","source_url":"https://github.com/we-solve/research/blob/main/problems/e2/prb_e20b1c52c4384f8db029c50d019f7e6e/contributions/con_7898437f31344beb85f2c4397f211e79/files/30007227.tex"}}],"tags":["openai"],"openai_claim":"solved","source_status":"open","status_source":"openai_claim","llm_status":"solved","llm_status_source":"openai_claim","completion":100,"completion_source":"openai_claim","we_solve":{"code":"WS-102778","record_code":"WS-102778","alias":"TOP-30007227","problem_id":"prb_e20b1c52c4384f8db029c50d019f7e6e","canonical_alias":"TOP-30007227","canonical_problem_id":"prb_e20b1c52c4384f8db029c50d019f7e6e","url":"https://we-solve.github.io/problems/condensation-in-every-dilute-hard-sphere-ground-state/","source_url":"https://github.com/we-solve/research/blob/main/problems/e2/prb_e20b1c52c4384f8db029c50d019f7e6e/statement.tex"}},"30007228":{"id":30007228,"problem_number":"LOCAL-30007228","legacy_ids":[],"title":"A spherical distribution of the low-temperature total quantum spin","collection":"ranked","rank":2772,"domain":"physics","domain_label":"Mathematical Physics","exact_target":"For every positive half-integer spin S and every sufficiently large fixed finite beta, do zero-field even periodic $Z^3$ Heisenberg cubes have volume-normalized total spin whose moment generating function tends to sinh(m|t|)/(m|t|) for some $m>0$ and every $t\\in R^3$? Require the averaged finite-volume spin-dot-spin sum divided by volume squared to tend to $m^2$.","definition_tex":"\\subsection{Definitions and mathematical statement}\n\\paragraph{Statement recorded in the supplied source.}\nFor every positive half-integer spin S and every sufficiently large fixed finite beta, do zero-field even periodic $Z^3$ Heisenberg cubes have volume-normalized total spin whose moment generating function tends to sinh(m|t|)/(m|t|) for some $m>0$ and every $t\\in R^3$? Require the averaged finite-volume spin-dot-spin sum divided by volume squared to tend to $m^2$.\n\n\\subsection{Short English statement}\nFor every positive half-integer spin S and every sufficiently large fixed finite beta, do zero-field even periodic $Z^3$ Heisenberg cubes have volume-normalized total spin whose moment generating function tends to sinh(m|t|)/(m|t|) for some $m>0$ and every $t\\in R^3$? Require the averaged finite-volume spin-dot-spin sum divided by volume squared to tend to $m^2$.\n\n\\subsection{Sources}\n\\begin{itemize}\n\\item[S1] Original question source or mathematical context.\n\\url{https://github.com/openai/math/blob/adc7f1241b42e322a6451854ab7e4b4c146bf78a/preprints/The-spherical-magnetization-law-for-the-three-dimensional-quantum-Heisenberg-ferromagnet-October-5-2026/build/sections/01-introduction.tex}.\n\\item[S2] OpenAI, manuscript citation page. Source of the formulation motivating this local problem.\n\\url{https://github.com/openai/math/blob/adc7f1241b42e322a6451854ab7e4b4c146bf78a/preprints/The-spherical-magnetization-law-for-the-three-dimensional-quantum-Heisenberg-ferromagnet-October-5-2026/README.md}.\n\\end{itemize}","definition_file":"attacks/open_problems/top_problems/definitions/30007228.tex","link":null,"external_url":null,"sources":[{"citation":"Original question source or mathematical context.","url":"https://github.com/openai/math/blob/adc7f1241b42e322a6451854ab7e4b4c146bf78a/preprints/The-spherical-magnetization-law-for-the-three-dimensional-quantum-Heisenberg-ferromagnet-October-5-2026/build/sections/01-introduction.tex"},{"citation":"OpenAI, manuscript citation page. Source of the formulation motivating this local problem.","url":"https://github.com/openai/math/blob/adc7f1241b42e322a6451854ab7e4b4